package com.example.preview;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.Instant;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class PreviewServiceTest {

    @Mock
    private PreviewCache previewCache;

    @Mock
    private MetadataFetcher metadataFetcher;

    @Mock
    private UrlRepository urlRepository;

    @Mock
    private PreviewConfig previewConfig;

    private PreviewService previewService;

    @BeforeEach
    void setUp() {
        when(previewConfig.getFetchTimeoutMs()).thenReturn(3000L);
        when(previewConfig.getCacheTtlSeconds()).thenReturn(86400L);
        previewService = new PreviewService(previewCache, metadataFetcher, urlRepository, previewConfig);
    }

    @Test
    void testAC_1_returnsPreviewFromCacheForKnownShortCode() throws Exception {
        String code = "aB3xQ";
        String targetUrl = "https://example.com/some/article";
        String fetchedAt = Instant.now().toString();
        String cacheExpiresAt = Instant.now().plusSeconds(86400).toString();

        PreviewDocument cached = new PreviewDocument(code, targetUrl, "Example Domain",
                "An example description", fetchedAt, cacheExpiresAt);

        when(previewCache.get(code)).thenReturn(Optional.of(cached));

        PreviewResult result = previewService.getPreview(code);

        assertNotNull(result);
        assertTrue(result.isSuccess());
        assertFalse(result.isNotFound());
        assertFalse(result.isUnavailable());

        PreviewDocument doc = result.getDocument();
        assertNotNull(doc);
        assertEquals(code, doc.getShortCode());
        assertEquals(targetUrl, doc.getTargetUrl());
        assertEquals("Example Domain", doc.getTitle());
        assertEquals("An example description", doc.getDescription());
        assertNotNull(doc.getFetchedAt());
        assertNotNull(doc.getCacheExpiresAt());

        verify(previewCache).get(code);
        verifyNoInteractions(metadataFetcher);
        verifyNoInteractions(urlRepository);
    }

    @Test
    void testAC_1_returnsPreviewFetchedFromUpstreamForKnownShortCodeCacheMiss() throws Exception {
        String code = "aB3xQ";
        String targetUrl = "https://example.com/some/article";
        String fetchedAt = Instant.now().toString();
        String cacheExpiresAt = Instant.now().plusSeconds(86400).toString();

        UrlRecord urlRecord = new UrlRecord(code, targetUrl);
        PreviewDocument fetched = new PreviewDocument(code, targetUrl, "Example Domain",
                "An example description", fetchedAt, cacheExpiresAt);

        when(previewCache.get(code)).thenReturn(Optional.empty());
        when(urlRepository.lookupByCode(code)).thenReturn(Optional.of(urlRecord));
        when(metadataFetcher.fetch(eq(targetUrl), anyLong())).thenReturn(fetched);

        PreviewResult result = previewService.getPreview(code);

        assertNotNull(result);
        assertTrue(result.isSuccess());
        assertFalse(result.isNotFound());
        assertFalse(result.isUnavailable());

        PreviewDocument doc = result.getDocument();
        assertNotNull(doc);
        assertEquals(code, doc.getShortCode());
        assertEquals(targetUrl, doc.getTargetUrl());
        assertNotNull(doc.getFetchedAt());
        assertNotNull(doc.getCacheExpiresAt());

        verify(previewCache).get(code);
        verify(urlRepository).lookupByCode(code);
        verify(metadataFetcher).fetch(eq(targetUrl), anyLong());
        verify(previewCache).put(eq(code), eq(fetched), anyLong());
    }

    @Test
    void testAC_1_returnsPreviewWithNullTitleAndDescriptionWhenMetadataAbsent() throws Exception {
        String code = "aB3xQ";
        String targetUrl = "https://example.com/some/article";
        String fetchedAt = Instant.now().toString();
        String cacheExpiresAt = Instant.now().plusSeconds(86400).toString();

        UrlRecord urlRecord = new UrlRecord(code, targetUrl);
        PreviewDocument fetched = new PreviewDocument(code, targetUrl, null, null, fetchedAt, cacheExpiresAt);

        when(previewCache.get(code)).thenReturn(Optional.empty());
        when(urlRepository.lookupByCode(code)).thenReturn(Optional.of(urlRecord));
        when(metadataFetcher.fetch(eq(targetUrl), anyLong())).thenReturn(fetched);

        PreviewResult result = previewService.getPreview(code);

        assertNotNull(result);
        assertTrue(result.isSuccess());

        PreviewDocument doc = result.getDocument();
        assertNotNull(doc);
        assertEquals(code, doc.getShortCode());
        assertEquals(targetUrl, doc.getTargetUrl());
        assertNull(doc.getTitle());
        assertNull(doc.getDescription());
        assertNotNull(doc.getFetchedAt());
        assertNotNull(doc.getCacheExpiresAt());
    }

    @Test
    void testAC_1_returnsNotFoundForUnknownShortCode() throws Exception {
        String code = "unknown";

        when(previewCache.get(code)).thenReturn(Optional.empty());
        when(urlRepository.lookupByCode(code)).thenReturn(Optional.empty());

        PreviewResult result = previewService.getPreview(code);

        assertNotNull(result);
        assertFalse(result.isSuccess());
        assertTrue(result.isNotFound());
        assertFalse(result.isUnavailable());
        assertNull(result.getDocument());
    }

    @Test
    void testAC_1_returns503WhenFetchFailsAndNoCachedData() throws Exception {
        String code = "aB3xQ";
        String targetUrl = "https://example.com/some/article";
        UrlRecord urlRecord = new UrlRecord(code, targetUrl);

        when(previewCache.get(code)).thenReturn(Optional.empty());
        when(urlRepository.lookupByCode(code)).thenReturn(Optional.of(urlRecord));
        when(metadataFetcher.fetch(eq(targetUrl), anyLong()))
                .thenThrow(new MetadataFetchException("upstream fetch timed out"));

        PreviewResult result = previewService.getPreview(code);

        assertNotNull(result);
        assertFalse(result.isSuccess());
        assertFalse(result.isNotFound());
        assertTrue(result.isUnavailable());
        assertNull(result.getDocument());
    }
}
