@ExtendWith(MockitoExtension.class)
class PreviewControllerTest {

    @Mock
    private PreviewService previewService;

    private PreviewController previewController;

    @BeforeEach
    void setUp() {
        previewController = new PreviewController(previewService);
    }

    @Test
    void testAC_1_returns200WithPreviewDocumentForKnownCode() throws Exception {
        String code = "aB3xQ";
        String targetUrl = "https://example.com/some/article";
        String fetchedAt = Instant.now().toString();
        String cacheExpiresAt = Instant.now().plusSeconds(86400).toString();

        PreviewDocument doc = new PreviewDocument(code, targetUrl, "Example Domain",
                "An example article about something", fetchedAt, cacheExpiresAt);
        PreviewResult successResult = PreviewResult.success(doc);

        when(previewService.getPreview(code)).thenReturn(successResult);

        HttpResponse response = previewController.getPreview(code);

        assertNotNull(response);
        assertEquals(200, response.getStatusCode());
        assertNotNull(response.getBody());

        Object body = response.getBody();
        assertTrue(body instanceof PreviewDocument);
        PreviewDocument responseDoc = (PreviewDocument) body;
        assertEquals(code, responseDoc.getShortCode());
        assertEquals(targetUrl, responseDoc.getTargetUrl());
        assertEquals("Example Domain", responseDoc.getTitle());
        assertEquals("An example article about something", responseDoc.getDescription());
        assertNotNull(responseDoc.getFetchedAt());
        assertNotNull(responseDoc.getCacheExpiresAt());
    }

    @Test
    void testAC_1_returns200WithPartialPreviewWhenTitleOrDescriptionAbsent() throws Exception {
        String code = "aB3xQ";
        String targetUrl = "https://example.com/some/article";
        String fetchedAt = Instant.now().toString();
        String cacheExpiresAt = Instant.now().plusSeconds(86400).toString();

        PreviewDocument doc = new PreviewDocument(code, targetUrl, null, null, fetchedAt, cacheExpiresAt);
        PreviewResult successResult = PreviewResult.success(doc);

        when(previewService.getPreview(code)).thenReturn(successResult);

        HttpResponse response = previewController.getPreview(code);

        assertNotNull(response);
        assertEquals(200, response.getStatusCode());
        assertNotNull(response.getBody());

        PreviewDocument responseDoc = (PreviewDocument) response.getBody();
        assertEquals(code, responseDoc.getShortCode());
        assertEquals(targetUrl, responseDoc.getTargetUrl());
        assertNull(responseDoc.getTitle());
        assertNull(responseDoc.getDescription());
        assertNotNull(responseDoc.getFetchedAt());
    }

    @Test
    void testAC_1_returns404ForUnknownShortCode() throws Exception {
        String code = "unknown";
        PreviewResult notFoundResult = PreviewResult.notFound();

        when(previewService.getPreview(code)).thenReturn(notFoundResult);

        HttpResponse response = previewController.getPreview(code);

        assertNotNull(response);
        assertEquals(404, response.getStatusCode());
        assertNotNull(response.getBody());
    }

    @Test
    void testAC_1_returns503WhenPreviewUnavailable() throws Exception {
        String code = "aB3xQ";
        PreviewResult unavailableResult = PreviewResult.unavailable("Preview unavailable: upstream fetch timed out");

        when(previewService.getPreview(code)).thenReturn(unavailableResult);

        HttpResponse response = previewController.getPreview(code);

        assertNotNull(response);
        assertEquals(503, response.getStatusCode());
        assertNotNull(response.getBody());
    }
}
